import React, { FC, useCallback, useState } from 'react';
import classNames from 'classnames';
import ClickableDiv from '../../atoms/clickableDiv/index';
import Text from '../../atoms/text/index';
import { ColorNameEnum } from '../../types/enums/textStyle';
import { CollapsableSectionTitle } from './collapsableSectionTitle';
import './index.less';

interface CollapsableSectionProps {
  title: string;
  length?: number;
  className?: string;
  expanded?: boolean;
  onToggle?(): void;
}

/**
 * A tabbed section that can be expanded
 *
 * @param length the length of items in the section
 * @param expanded an optional prop to pass in the expanded state,
 * if not passed then uses inner state based on toggling.
 * @param onToggle callback for when the section is expanded/closed.
 */
const CollapsableSection: FC<CollapsableSectionProps> = ({
  children,
  title,
  length,
  className,
  expanded: expandedProp,
  onToggle: onToggleProp,
}) => {
  const [expandedState, setExpandedState] = useState(true);

  const onToggle = useCallback(() => {
    if (onToggleProp) onToggleProp();
    setExpandedState((state) => !state);
  }, [onToggleProp]);

  const expanded = expandedProp !== undefined ? expandedProp : expandedState;

  const ExpandingArrow: FC = () =>
    expanded ? (
      <ClickableDiv clickHandler={onToggle}>
        <Text className="icon-x collapsable-section-header-icon" colorName={ColorNameEnum.theme} />
      </ClickableDiv>
    ) : (
      <ClickableDiv clickHandler={onToggle}>
        <Text
          className="icon-chevron-2 collapsable-section-header-icon"
          colorName={ColorNameEnum.theme}
        />
      </ClickableDiv>
    );

  return (
    <div className={classNames('collapsable-section', className, { expanded })}>
      <div className="collapsable-section-header">
        <CollapsableSectionTitle title={title} listLength={length} onTitleClicked={onToggle} />
        {onToggleProp && <ExpandingArrow />}
      </div>
      <div
        className="collapsable-section-items"
        style={{ display: !expanded ? 'none' : undefined }}
      >
        {children}
      </div>
    </div>
  );
};

export default CollapsableSection;
