import React from 'react';
import ClickableDiv from '../../atoms/clickableDiv/index';
import Text from '../../atoms/text/index';
import { WeightEnum, SizeEnum } from '../../types/enums/textStyle';

export type Props = {
  listLength?: number;
  title: string;
  onTitleClicked: () => void;
};

export function CollapsableSectionTitle({ title, listLength, onTitleClicked }: Props) {
  return (
    <>
      <ClickableDiv className="collapsable-section-header-content" clickHandler={onTitleClicked}>
        <Text
          className="collapsable-section-title"
          size={SizeEnum['14px']}
          weight={WeightEnum.bold}
        >
          {title}
          &nbsp;
          {(listLength || listLength === 0) && (
            <span className="list-length text-normal">{listLength}</span>
          )}
        </Text>
      </ClickableDiv>
    </>
  );
}
